            b = FTypeTuple.make(df).subtypeOf(FTypeTuple.make(dg));
        }
        catch (FortressException ex) {
            // no instance of g holds f's declared domain
        }
        catch (EmptyLatticeIntervalError ex) {
            // no instance of g holds f's declared domain
        }
        methodDeclaredBelowMemo.put(key, b);
    }
    return b;
}

